#include "motors.h"

/**
 * @brief  Initializes the motor PWM signals and arms the ESCs.
 * @param  htim: Pointer to the timer handler (e.g., &htim2) 
 *               generated by STM32CubeMX.
 */
void motors_init(TIM_HandleTypeDef *htim) 
{
    /* 
     * STEP 1: START THE HARDWARE TIMERS
     * We must explicitly tell the STM32 to begin generating the PWM signals
     * on the specific channels we configured in CubeMX (CH1 and CH2).
     */
    HAL_TIM_PWM_Start(htim, TIM_CHANNEL_1);
    HAL_TIM_PWM_Start(htim, TIM_CHANNEL_2);

    /* 
     * STEP 2: SET TO NEUTRAL
     * The macro __HAL_TIM_SET_COMPARE writes a value directly into the 
     * Capture Compare Register (CCR). Because our timer ticks at 1 MHz, 
     * putting '1500' here generates an exact 1500 microsecond pulse.
     */
    __HAL_TIM_SET_COMPARE(htim, TIM_CHANNEL_1, PWM_NEUTRAL);
    __HAL_TIM_SET_COMPARE(htim, TIM_CHANNEL_2, PWM_NEUTRAL);

    /* 
     * STEP 3: THE ESC ARMING SEQUENCE
     * Brushless ESCs have a safety feature: they will not spin the motor 
     * upon power-up until they receive a continuous, valid "Neutral" signal 
     * for a few seconds. We use a blocking delay here during initialization 
     * to guarantee the ESCs arm before the main loop begins.
     * Note: This is the ONLY place in the codebase where HAL_Delay(3000) is acceptable!
     */
    HAL_Delay(3000); 
}

/**
 * @brief  Sets the speeds of both thrusters safely.
 * @param  htim: Pointer to the timer handler (e.g., &htim2)
 * @param  left_throttle: Commanded speed (-500 to 500)
 * @param  right_throttle: Commanded speed (-500 to 500)
 */
void motors_set_speeds(TIM_HandleTypeDef *htim, int16_t left_throttle, int16_t right_throttle) 
{
    /* 
     * STEP 1: CLAMP THE INPUTS
     * This is a safety feature. We expect inputs from -500 to 500.
     * If a bug in the navigation logic sends a value of 10,000, 
     * this clamping prevents the PWM signal from breaking the 1000-2000us 
     * boundary and crashing the ESC.
     */
    if (left_throttle > 500) left_throttle = 500;
    if (left_throttle < -500) left_throttle = -500;
    
    if (right_throttle > 500) right_throttle = 500;
    if (right_throttle < -500) right_throttle = -500;

    /* 
     * STEP 2: MAP TO PHYSICAL MICROSECONDS
     * We add the raw throttle value (-500 to 500) to our 1500us neutral point.
     * Example: If left_throttle is 0, pulse is 1500 (stopped).
     * Example: If left_throttle is 500, pulse is 2000 (full forward).
     * Example: If left_throttle is -200, pulse is 1300 (slow reverse).
     */
    uint32_t left_pulse_us  = PWM_NEUTRAL + left_throttle;
    uint32_t right_pulse_us = PWM_NEUTRAL + right_throttle;

    /* 
     * STEP 3: UPDATE THE HARDWARE
     * Write the newly calculated pulse widths to the timer channels.
     */
    __HAL_TIM_SET_COMPARE(htim, TIM_CHANNEL_1, left_pulse_us);
    __HAL_TIM_SET_COMPARE(htim, TIM_CHANNEL_2, right_pulse_us);
}

/**
 * @brief  Immediately stops both motors.
 * @param  htim: Pointer to the timer handler
 */
void motors_stop(TIM_HandleTypeDef *htim) 
{
    /*
     * Returns both ESCs to the 1500us neutral point to halt the thrusters.
     * This is useful for fail-safes (e.g., sonar detects an immediate collision).
     */
    __HAL_TIM_SET_COMPARE(htim, TIM_CHANNEL_1, PWM_NEUTRAL);
    __HAL_TIM_SET_COMPARE(htim, TIM_CHANNEL_2, PWM_NEUTRAL);
}
